import{_ as a,o as e,c as n,a6 as o}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"连接与服务发现","description":"Alt-Svc、DNS HTTPS 记录、GOAWAY 的双向语义与回落策略。","frontmatter":{"title":"连接与服务发现","description":"Alt-Svc、DNS HTTPS 记录、GOAWAY 的双向语义与回落策略。","source":"https://daiw.org/manual/http2-3/h3-connection"},"headers":[],"relativePath":"manual/computer-programming/http2-3/h3-connection.md","filePath":"manual/computer-programming/http2-3/h3-connection.md"}'),s={name:"manual/computer-programming/http2-3/h3-connection.md"};function r(d,t,i,l,h,c){return e(),n("div",null,[...t[0]||(t[0]=[o(`<h1 id="连接与服务发现" tabindex="-1">连接与服务发现 <a class="header-anchor" href="#连接与服务发现" aria-label="Permalink to &quot;连接与服务发现&quot;">​</a></h1><p>Alt-Svc、DNS HTTPS 记录、GOAWAY 的双向语义与回落策略。</p><h2 id="发现问题" tabindex="-1">发现问题 <a class="header-anchor" href="#发现问题" aria-label="Permalink to &quot;发现问题&quot;">​</a></h2><p>客户端不能凭空知道某个站点支持 h3——直接发 UDP 包给一个不支持的服务器只会超时。所以 h3 <strong>必须先被发现</strong>。</p><p>三条路径：</p><h3 id="_1-alt-svc-字段-rfc-7838" tabindex="-1">1. Alt-Svc 字段（RFC 7838） <a class="header-anchor" href="#_1-alt-svc-字段-rfc-7838" aria-label="Permalink to &quot;1. Alt-Svc 字段（RFC 7838）&quot;">​</a></h3><p>服务端在 h2/1.1 响应里声明「我还有个 h3 端点」：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">alt-svc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h3=&quot;:443&quot;; ma=86400</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">alt-svc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h3=&quot;:443&quot;; ma=86400, h2=&quot;:443&quot;; ma=3600</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><table tabindex="0"><thead><tr><th>参数</th><th>含义</th></tr></thead><tbody><tr><td><code>h3=&quot;:443&quot;</code></td><td>协议 ALPN + 端口（主机省略表示同主机）</td></tr><tr><td><code>ma</code></td><td>max-age，该通告的有效秒数（默认 86400）</td></tr><tr><td><code>persist=1</code></td><td>网络变更后仍保留该记录</td></tr></tbody></table><p>客户端行为：</p><ul><li><strong>本次请求仍走当前协议</strong>，把通告存入 Alt-Svc 缓存。</li><li><strong>后续</strong>请求尝试用 h3 连接；成功则持续使用，失败则回落。</li><li>这意味着<strong>首次访问必然不走 h3</strong>——至少要一个来回才能升级。</li></ul><h3 id="_2-dns-https-svcb-记录-rfc-9460" tabindex="-1">2. DNS HTTPS/SVCB 记录（RFC 9460） <a class="header-anchor" href="#_2-dns-https-svcb-记录-rfc-9460" aria-label="Permalink to &quot;2. DNS HTTPS/SVCB 记录（RFC 9460）&quot;">​</a></h3><p>解决 Alt-Svc 的「首访必慢一拍」问题——把发现提前到 DNS 查询阶段：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>example.com.  3600  IN  HTTPS  1 . alpn=&quot;h3,h2&quot; port=443 ipv4hint=203.0.113.1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>客户端在解析域名时就知道支持 h3，<strong>第一个请求即可直发 QUIC</strong>。同时 <code>ipv4hint</code>/<code>ipv6hint</code> 还能省一次 A/AAAA 查询，<code>ech</code> 参数用于加密 SNI。</p><p>这是目前推荐的方式，主流浏览器与 CDN 均已支持。</p><h3 id="_3-先验知识" tabindex="-1">3. 先验知识 <a class="header-anchor" href="#_3-先验知识" aria-label="Permalink to &quot;3. 先验知识&quot;">​</a></h3><p>客户端被显式配置为使用 h3（如 API 客户端固定配置），跳过发现。</p><h2 id="回落策略" tabindex="-1">回落策略 <a class="header-anchor" href="#回落策略" aria-label="Permalink to &quot;回落策略&quot;">​</a></h2><p>h3 跑在 UDP 上，而 UDP 在部分网络中被封禁或严重限速。客户端<strong>必须</strong>具备回落能力：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 并发或竞速发起 QUIC 连接与 TCP 连接</span></span>
<span class="line"><span>2. QUIC 在超时内握手成功 → 用 h3，标记该网络可用 UDP</span></span>
<span class="line"><span>3. QUIC 超时/被拒 → 用已经建好的 TCP 连接走 h2/1.1</span></span>
<span class="line"><span>4. 记录失败，一段时间内不再对该网络/该源尝试 h3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Chrome 等实现使用「竞速（racing）」：同时发起两种连接，先成功者胜出，另一条丢弃。代价是多一点连接开销，换取无感回落。</p><p>服务端侧：<strong>必须同时保留 h2/1.1 端点</strong>。只提供 h3 会让相当比例的用户完全无法访问。</p><h2 id="goaway" tabindex="-1">GOAWAY <a class="header-anchor" href="#goaway" aria-label="Permalink to &quot;GOAWAY&quot;">​</a></h2><p>h3 也有 <code>GOAWAY</code>，但语义比 h2 更完整——它是<strong>双向</strong>的：</p><table tabindex="0"><thead><tr><th>发送方</th><th>载荷含义</th></tr></thead><tbody><tr><td><strong>服务端</strong></td><td>最大的<strong>已处理</strong>请求流 ID。大于该值的请求一定未被处理</td></tr><tr><td><strong>客户端</strong></td><td>最大的<strong>推送 ID</strong>（表示不再接受更大的推送）</td></tr></tbody></table><p>h2 的 <a href="/Front2Full/manual/computer-programming/http2-3/h2-connection"><code>GOAWAY</code></a> 只能由任一端发送并标注 Last-Stream-ID；h3 明确区分了两个方向的用途。</p><p>规则：</p><ul><li>只能在<strong>控制流</strong>上发送。</li><li>可以发<strong>多次</strong>，但后发的 ID <strong>MUST NOT 大于</strong>先发的（只能收紧，不能放宽）——违反 → <code>H3_ID_ERROR</code>。</li><li>与 h2 相同的两阶段优雅关闭做法同样适用：先发大值表达意图，处理完在途请求后再发真实边界。</li></ul><h2 id="连接关闭" tabindex="-1">连接关闭 <a class="header-anchor" href="#连接关闭" aria-label="Permalink to &quot;连接关闭&quot;">​</a></h2><p>QUIC 层提供了 h2 没有的能力：</p><table tabindex="0"><thead><tr><th>场景</th><th>机制</th></tr></thead><tbody><tr><td>优雅关闭</td><td>h3 <code>GOAWAY</code> → 处理完 → QUIC <code>CONNECTION_CLOSE</code></td></tr><tr><td>立即关闭</td><td>QUIC <code>CONNECTION_CLOSE</code>（带错误码与原因短语）</td></tr><tr><td>空闲超时</td><td>QUIC 传输参数 <code>max_idle_timeout</code>，双方取较小值</td></tr><tr><td>无状态重置</td><td>服务端重启丢失状态后，用 Stateless Reset Token 告知对端「这条连接我不认识了」，避免客户端长时间重试</td></tr></tbody></table><p><strong>无状态重置</strong>是 TCP 的 <code>RST</code> 在加密传输上的等价物——因为服务端重启后无法解密该连接的包，只能靠预先分发的 token 来证明「确实是我发的重置」。</p><h2 id="与-h2-的连接管理对照" tabindex="-1">与 h2 的连接管理对照 <a class="header-anchor" href="#与-h2-的连接管理对照" aria-label="Permalink to &quot;与 h2 的连接管理对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>h2</th><th>h3</th></tr></thead><tbody><tr><td>连接前言</td><td><code>PRI * HTTP/2.0</code> 魔数</td><td>无（ALPN 已确定）</td></tr><tr><td>参数协商</td><td>流 0 的 <code>SETTINGS</code> + ACK</td><td>控制流首帧 <code>SETTINGS</code>，<strong>无 ACK、不可重发</strong></td></tr><tr><td>保活</td><td>h2 <code>PING</code> 帧</td><td><strong>QUIC</strong> <code>PING</code> 帧</td></tr><tr><td>单流终止</td><td><code>RST_STREAM</code></td><td><strong>QUIC</strong> <code>RESET_STREAM</code> / <code>STOP_SENDING</code></td></tr><tr><td>优雅关闭</td><td><code>GOAWAY</code></td><td><code>GOAWAY</code>（双向语义）+ QUIC <code>CONNECTION_CLOSE</code></td></tr><tr><td>换网络</td><td><strong>断连重建</strong></td><td><strong>连接迁移</strong>，无感</td></tr></tbody></table><p><code>STOP_SENDING</code> 是 QUIC 独有的：它表示「别再往这条流发了」，而 <code>RESET_STREAM</code> 是「我不发了」。h2 的 <code>RST_STREAM</code> 把两个方向混为一谈，QUIC 拆开了。</p><h2 id="_0-rtt-与幂等性" tabindex="-1">0-RTT 与幂等性 <a class="header-anchor" href="#_0-rtt-与幂等性" aria-label="Permalink to &quot;0-RTT 与幂等性&quot;">​</a></h2><p>复用<a href="/Front2Full/manual/computer-programming/http2-3/quic-transport">前文</a>的结论，落到 HTTP 层：</p><ul><li>客户端 <strong>SHOULD</strong> 只在 0-RTT 中发送安全且幂等的请求。</li><li>服务端若不愿在 0-RTT 中处理某请求，返回 <a href="/Front2Full/manual/computer-programming/http11/status-4xx"><code>425 Too Early</code></a>；客户端 <strong>MUST</strong> 在握手完成后重发。</li><li>服务端也可整体拒绝 0-RTT（不下发会话票据或忽略早期数据）。</li></ul><p>这是 <a href="/Front2Full/manual/computer-programming/http11/status-4xx"><code>425</code> 这个状态码存在的真正场景</a>——它在 1.1 时代几乎无用武之地。</p><p>第 2 部分结束。下一篇：<a href="/Front2Full/manual/computer-programming/http2-3/version-comparison">三版全面对照</a>。</p>`,41)])])}const g=a(s,[["render",r]]);export{u as __pageData,g as default};
